	context: RewardChatMessage[];
	completion: string;
	reward: number;
	signals: {
		explicit?: RewardSourceSignal;
		inferred?: RewardSourceSignal;
		quiz?: RewardSourceSignal;
		judge?: JudgeScore & { score: number };
	};
	scored: boolean;
}

export interface NormalizedRewardMessage {
	role: "user" | "assistant";
	content: string;
	timestamp?: number;
	shortAssistant?: boolean;
}

export type ExportJudge = (examples: RewardedTurn[]) => Promise<Array<JudgeScore | null>>;

export interface RewardStats {
	scored: number;
	unscored: number;
	bySource: {
		explicit: number;
		inferred: number;
		quiz: number;
		judge: number;
	};
	distribution: [number, number, number, number, number];
}

export interface PreferencePair {
	prompt: RewardChatMessage[];
	chosen: string;
	rejected: string;
	chosenReward: number;
	rejectedReward: number;
	rewardGap: number;
}

export function buildExplicitResponsePreference({
	originalMessages,
	alternativeMessages,
	originalMessageTimestamp,
	preference,
	persona,
}: {
	originalMessages: NormalizedRewardMessage[];
	alternativeMessages: NormalizedRewardMessage[];
	originalMessageTimestamp: number;
	preference: "original" | "alternative";
	persona?: string;
}): PreferencePair | null {
	const originalIndex = originalMessages.findIndex((message) => (
		message.role === "assistant" && message.timestamp === originalMessageTimestamp
	));
	const alternative = [...alternativeMessages].reverse().find((message) => message.role === "assistant");
	if (originalIndex < 0 || !alternative) return null;
	const original = originalMessages[originalIndex];
	const prior = originalMessages.slice(0, originalIndex).map((message): RewardChatMessage => ({
		role: message.role,
		content: message.content,
	}));
	const prompt: RewardChatMessage[] = persona?.trim()
		? [{ role: "system", content: persona.trim() }, ...prior]
		: prior;
	const chosen = preference === "alternative" ? alternative.content : original.content;
	const rejected = preference === "alternative" ? original.content : alternative.content;
	if (!chosen.trim() || !rejected.trim() || chosen === rejected) return null;
	return {
		prompt,
		chosen,
		rejected,
		chosenReward: 1,
		rejectedReward: 0,
		rewardGap: 1,
	};
}

function clamp01(value: number): number {
	if (!Number.isFinite(value)) return REWARD_NEUTRAL;
	return Math.max(0, Math.min(1, value));
}

function weightedMean(entries: Array<{ score: number; weight: number }>): number | null {
	const present = entries.filter((entry) => Number.isFinite(entry.score));
	const total = present.reduce((sum, entry) => sum + entry.weight, 0);
	if (total <= 0) return null;
	return clamp01(present.reduce((sum, entry) => sum + entry.score * entry.weight, 0) / total);
}

function timestampFromMessageId(messageId?: string): number | null {
	if (!messageId) return null;
	const match = /-(\d+)$/.exec(messageId);
	if (!match) return null;
	const value = Number(match[1]);
	return Number.isFinite(value) ? value : null;
}

function promptKey(context: RewardChatMessage[]): string {
	return JSON.stringify(context.map((message) => [message.role, message.content]));
}

function quizScore(record: QuizResultRecord): number {
	if (typeof record.weightedScore === "number") return clamp01(record.weightedScore);
	return clamp01(record.score / Math.max(1, record.totalQuestions));
}

