type TrainingSplit = "train" | "validation";
type TrainingQualityStatus = "accepted" | "unscored" | "review" | "rejected" | "reference";

interface CanonicalTrainingRecord {
	schemaVersion: 2;
	id: string;
	split: TrainingSplit;
	task: "supervised-finetuning" | "preference-learning" | "reference";
