	const manifest = JSON.parse(result.manifestJson) as Record<string, any>;
	manifest.files = files.map(({ path, purpose, records }) => ({ path, purpose, records }));
	const dataCard = buildDataCard(manifest, files);
	files.unshift({ path: "README.md", purpose: "Dataset card and training guidance.", content: dataCard });
	manifest.files.unshift({ path: "README.md", purpose: "Dataset card and training guidance." });
	files.unshift({
		path: "manifest.json",
		purpose: "Machine-readable export settings, counts, quality summary, and file catalog.",
		content: `${JSON.stringify(manifest, null, 2)}\n`,
	});

	const zipped = zipSync(Object.fromEntries(files.map((file) => [file.path, strToU8(file.content)])), { level: 6 });
	return {
		bytes: zipped,
		filename: `keating-training-${archiveTimestamp(manifest.generatedAt)}.zip`,
		files: files.map(({ content: _content, ...file }) => file),
	};
}

