								{label}
							</text>
							<rect
								x={x}
								y={y}
								width={w}
								height={rowH}
								rx={3}
								fill={color}
								opacity={s.endedAt ? 0.85 : 0.55}
							>
								<title>
									{primary}
									{"\n"}Started: {new Date(s.startedAt).toLocaleString()}
									{s.endedAt ? `\nEnded: ${new Date(s.endedAt).toLocaleString()}` : "\n(in progress)"}
